/**
 * Test subflow for AssignSubflowOutputs with datapills
 * Tests: action outputs, subflow inputs, and template expressions
 */
export const assignSubflowOutputsDatapills = Subflow(
    {
        $id: Now.ID['assign-subflow-outputs-datapills'],
        name: 'AssignSubflowOutputs Datapills Test',
        description: 'Test AssignSubflowOutputs with various datapill types',
        inputs: {
            inputData: StringColumn({
                label: 'Input Data',
                mandatory: true,
            }),
        },
        outputs: {
            actionData: StringColumn({
                label: 'Action Data',
                mandatory: true,
            }),
            inputData: StringColumn({
                label: 'Input Data Echo',
                mandatory: true,
            }),
            message: StringColumn({
                label: 'Message',
                mandatory: true,
            }),
        },
    },
    (params) => {
        // Execute action to get outputs for datapill testing
        const actionResult = wfa.action(
            action.core.log,
            {
                $id: Now.ID['test-action-for-outputs-instance'],
                uuid: 'bbbbbbbb-cccc-dddd-eeee-ffffffffffff',
            },
            {
                log_message: wfa.dataPill(params.inputs.inputData, 'string'),
            }
        )

        // Test 1: AssignSubflowOutputs with action output datapill
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-action-pill'],
                annotation: 'Assign outputs with action datapills',
            },
            params.outputs,
            {
                actionData: wfa.dataPill(actionResult.__action_status__.message, 'string'),
            }
        )

        // Test 2: AssignSubflowOutputs with subflow input datapill
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-input-pill'],
                annotation: 'Assign outputs with subflow input datapills',
            },
            params.outputs,
            {
                inputData: wfa.dataPill(params.inputs.inputData, 'string'),
            }
        )

        // Test 3: AssignSubflowOutputs with template expression
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-template'],
                annotation: 'Assign outputs with template expressions',
            },
            params.outputs,
            {
                message: `Processing completed for input: ${wfa.dataPill(params.inputs.inputData, 'string')}`,
            }
        )
    }
)
